head.script:
var jsonData = { "aa": "test" };

scwin.onpageload = function() {
	var submissionObj = {
		"id": "submission2",
		"ref": "data:json,dc_reqDataMap",
		"target": "data:json,dc_resDataMap",
		"action": "/data/sampleData.json",
		"method": "post",
		"mediatype": "application/json",
		"encoding": "UTF-8",
		"mode": "asynchronous",
		"processMsg": "processing ~ ~ ~ ",
	};
	$p.createSubmission(submissionObj);

	$p.getComponentById("submission1");
	$p.getComponentById("submission2");
};

scwin.checkVal = function() {
	return $p.getComponentById("submission2").singleMode == false;
};
